const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const coordinates = [86.428836, 35.879797]; // (longitude, latitude)
    const point = ee.Geometry.Point(coordinates);
    const radiusKm = 50;
    const geometry = point.buffer(radiusKm * 1000); // Buffer in meters

    // The question asks for August 11, 2024, which is in the future.
    // We will use the latest available Sentinel-2 data for August 2023
    // as the closest approximation to "current" conditions for water bodies.
    const startDate = '2023-08-01';
    const endDate = '2023-08-31';

    // 2. Data Acquisition & Check
    let collection = ee.ImageCollection('COPERNICUS/S2_SR')
      .filterBounds(geometry)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20)); // Filter for less than 20% cloudiness

    const collectionSize = await collection.size().getInfo();
    console.log(`Sentinel-2 images found for Aug 2023: ${collectionSize}`);

    if (collectionSize === 0) {
      console.log("C1: No Sentinel-2 images found for the specified date range and location.");
      console.log("C1");
      return;
    }

    // Create a cloud mask function for Sentinel-2 SR data
    function maskS2clouds(image) {
      const qa = image.select('QA60');
      // Bits 10 and 11 are clouds and cirrus, respectively.
      const cloudBitMask = 1 << 10;
      const cirrusBitMask = 1 << 11;
      // Both flags should be set to zero, indicating clear conditions.
      const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
        .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
      return image.updateMask(mask).divide(10000)
        .select(['B2', 'B3', 'B4', 'B8']); // Select relevant bands for NDWI
    }

    // Apply cloud mask and create a median composite
    const composite = collection.map(maskS2clouds).median();

    // Check if the composite is empty or has no valid pixels
    const bandNames = await composite.bandNames().getInfo();
    if (bandNames.length === 0) {
      console.log("C2: Composite image is empty after cloud masking.");
      console.log("C2");
      return;
    }

    const initialPixelCount = await composite.select('B8').reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: 100, // Using 100m for initial pixel count
      maxPixels: 1e9
    }).get('B8').getInfo();
    console.log(`Initial valid pixels in composite (B8): ${initialPixelCount}`);

    if (initialPixelCount === 0) {
      console.log("C2: No valid pixels remain after cloud masking in the region of interest.");
      console.log("C2");
      return;
    }

    // 3. Water Body Detection (NDWI)
    // NDWI = (Green - NIR) / (Green + NIR)
    // Sentinel-2 bands: B3 = Green, B8 = NIR
    const ndwi = composite.normalizedDifference(['B3', 'B8']);

    // Threshold NDWI to classify water. Common threshold is > 0.
    const waterMask = ndwi.gt(0);

    // Get the pixel count of water.
    const waterPixelCount = await waterMask.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: 100, // Use 100m scale for water detection
      maxPixels: 1e9
    }).get('nd').getInfo();

    console.log(`Water pixels detected: ${waterPixelCount}`);

    if (waterPixelCount === null || waterPixelCount === undefined) {
      console.log("C3: Calculation failure for water pixel count.");
      console.log("C3");
      return;
    }

    if (waterPixelCount === 0) {
      console.log("No water pixels detected in the region.");
      console.log("B"); // No lakes means 0 lakes, which is not > 3.
      return;
    }

    // 4. Identify individual water bodies (connected components)
    // Use an 8-way connectivity for connected components
    const labeledWater = waterMask.connectedComponents({
      connectedness: 8,
      maxSize: 256 // Max components to label
    });

    // We want to count distinct "lakes", so we need to filter by size.
    // Calculate the area of each component.
    const minLakeAreaSqM = 10000; // Define a minimum area for a feature to be considered a 'lake' (e.g., 1 hectare = 10,000 sq meters)
    const lakeThreshold = 0.001; // 10000 sq meters / (100m * 100m) = 1 pixel for 100m resolution.

    // Calculate the area of each component.
    const objectArea = labeledWater.select('labels')
      .rename('labels')
      .multiply(ee.Image.pixelArea()) // Get pixel area for each pixel
      .reduceRegion({
        reducer: ee.Reducer.sum().group({
          groupField: 0,
          groupName: 'label'
        }),
        geometry: geometry,
        scale: 100, // Use 100m scale for area calculation
        maxPixels: 1e9
      });

    // Convert the result to a list of features to process in client-side
    const areaList = await objectArea.getInfo();
    if (!areaList || !areaList.groups) {
      console.log("C3: Failed to calculate object areas or no groups found.");
      console.log("C3");
      return;
    }

    let lakeCount = 0;
    areaList.groups.forEach(group => {
      const area_sq_m = group.sum; // Area in square meters
      // console.log(`Label ${group.label}: Area = ${area_sq_m.toFixed(2)} sq m`);
      if (area_sq_m >= minLakeAreaSqM) {
        lakeCount++;
      }
    });

    console.log(`Number of distinct lakes (> ${minLakeAreaSqM} sq m): ${lakeCount}`);

    // 5. Validation & Final Answer
    if (lakeCount === null || lakeCount === undefined) {
      console.log("C3: Final lake count is invalid.");
      console.log("C3");
    } else if (lakeCount > 3) {
      console.log("A");
    } else {
      console.log("B");
    }

  } catch (error) {
    console.error("D: An error occurred:", error);
    console.log("D");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
